-- id:       fn-sla-compliance
-- title:    SLA compliance by department (stored function)
-- concept:  Calling fn_sla_compliance(dept, from, to)
-- rubric:   8 · Function
-- purpose:  A PL/pgSQL function returns the share of complaints resolved within SLA for a department and date range.
-- GENERATED by web/scripts/export-queries.ts from src/lib/data/mock/lab.ts. Edit there, then run npm run db:queries.

SELECT d.department_name,
       fn_sla_compliance(d.department_id, now() - interval '90 days', now()) AS sla_met_pct
FROM department d
ORDER BY sla_met_pct DESC NULLS LAST;
